using RecursiveAI.OneCrypto;
using RecursiveAI.OneCrypto.Validation;

namespace OneCrypto.Smoke;

/// <summary>
/// One path validation in an app that is trimmed, AOT-compiled or run in the browser: a three-certificate P-256 chain (generated by
/// tools/gen-validation-smoke.sh, throwaway keys) validated at a fixed instant, and the same chain refused at an instant before it exists.
/// Signatures verify through the dispatch, so the browser uses the managed verify-only ECDSA.
/// </summary>
internal static class ValidationSmoke
{
    private const string Root = "";
    private const string Ca = "";
    private const string Leaf = "";

    public static bool Run()
    {
        var root = Certificate.Parse(Convert.FromBase64String(Root));
        var ca = Certificate.Parse(Convert.FromBase64String(Ca));
        var leaf = Certificate.Parse(Convert.FromBase64String(Leaf));
        ValidationOptions Options(DateTimeOffset at) => new()
        {
            TrustAnchors = [TrustAnchor.FromCertificate(root)],
            Intermediates = [ca],
            ReferenceTime = at,
            WebPki = new WebPkiProfile { ServerName = "smoke.example.test" },
        };

        ValidationReport ok = PathValidator.Validate(leaf, Options(new DateTimeOffset(2027, 1, 1, 0, 0, 0, TimeSpan.Zero)));
        ValidationReport early = PathValidator.Validate(leaf, Options(new DateTimeOffset(2026, 6, 1, 0, 0, 0, TimeSpan.Zero)));
        bool good = ok.IsValid && ok.SelectedPath is { Certificates.Length: 2 } && !early.IsValid && early.DecidingRule?.Rule == ValidationRule.Validity;
        Console.WriteLine($"validation: {ok.Verdict}, earlier instant: {early.Verdict} ({early.DecidingRule?.Rule})");
        if (!good)
        {
            Console.WriteLine($"  deciding: {ok.DecidingRule}");
            foreach (RejectedCandidate r in ok.Rejected)
            {
                Console.WriteLine($"  rejected candidate: {r.Reason}");
            }
        }

        return good;
    }
}
